async function setupProjectWithAgents(
  dir: string,
  agents: Agent[],
): Promise<void> {
  initGitRepo(dir);

  // Use traditional layout: manifest in the dir root itself
  // Write manifest
  await fs.writeFile(
    path.join(dir, "kynetic.yaml"),
    YAML.stringify({ kynetic: "1", title: "Test Project" }),
    "utf-8",
  );

  // Write meta with agents
  await fs.writeFile(
    path.join(dir, "kynetic.meta.yaml"),
    YAML.stringify({
      kynetic_meta: "1.0",
      agents: agents.map((a) => ({
        _ulid: a._ulid,
        id: a.id,
        name: a.name,
        dispatch: a.dispatch ?? [],
        concurrency: a.concurrency,
        adapter: a.adapter,
        budget: a.budget,
        auto_approve: a.auto_approve ?? false,
      })),
    }),
    "utf-8",
  );

  // Write empty tasks file
  await fs.writeFile(
    path.join(dir, "project.tasks.yaml"),
    YAML.stringify({ tasks: [] }),
    "utf-8",
  );
}

/**
 * Write tasks to the project tasks file.
 */
async function writeTasks(dir: string, tasks: Array<{
  _ulid: string;
  status: string;
  automation?: string;
  tags?: string[];
  priority?: number;
}>): Promise<void> {
  await fs.writeFile(
    path.join(dir, "project.tasks.yaml"),
    YAML.stringify({
      tasks: tasks.map((t) => ({
        _ulid: t._ulid,
        type: "task",
        title: `Task ${t._ulid}`,
        status: t.status,
        automation: t.automation,
        tags: t.tags ?? [],
        priority: t.priority,
        created_at: new Date().toISOString(),
        notes: [],
        todos: [],
      })),
    }),
    "utf-8",
  );
}

