      enqueueCount++;
    });

    await engine.start();
    // Reset after bootstrap
    enqueueCount = 0;

    const now = Date.now();
    const taskId = testUlid("TASK");
    const change: TaskStateChange = {
      taskId,
      taskRef: `@${taskId}`,
