  try {
    // Use 'where' on Windows, 'which' on Unix
    const cmd = process.platform === 'win32' ? 'where' : 'which';
    execSync(`${cmd} bun`, { stdio: 'ignore' });
    return true;
  } catch {
    return false;
  }
}

