   157→        uncommitted.push(filePath);
   158→        // Clean up remaining staging files
   159→        for (const [remainingPath, remainingStagingPath] of stagingMap) {
   160→          if (!committed.includes(remainingPath) && remainingStagingPath) {
   161→            await fs.rm(remainingStagingPath, { force: true }).catch(() => {});
   162→          }
   163→        }
