   165→          `Batch flush commit failed: ${err instanceof Error ? err.message : err}.\n` +
   166→            `Committed (${committed.length}): ${committed.join(", ") || "none"}\n` +
   167→            `Uncommitted (${uncommitted.length + (stagingMap.size - committed.length - 1)}): remaining files`,
   168→        );
   169→      }
   170→    }
   171→  }
