  tasksCompleted: string[];
} {
  const tasksStarted: string[] = [];
  const tasksCompleted: string[] = [];

  for (const event of events) {
    if (event.type === "session.update") {
      const data = event.data as {
        update?: {
          sessionUpdate?: string;
          rawInput?: { command?: string };
