        if (/\btask start\b/.test(command)) {
          const ref = extractTaskRef(command);
          if (ref) tasksStarted.push(ref);
        } else if (/\btask complete\b/.test(command)) {
          const ref = extractTaskRef(command);
          if (ref) tasksCompleted.push(ref);
        }
      }
    }
  }

