python3 << 'EOF'
import json

# Find all codex sessions that ran after Feb 24 - look at 01KJMTEA
path = '/home/chapel/Projects/kynetic-spec/.kspec/sessions/01KJMTEASC25JM78T6MY1NW3XF/events.jsonl'
lines = open(path).readlines()

# Find ALL commands in rawInput
for line in lines:
    try:
        ev = json.loads(line)
        data = ev.get('data', {})
        update = data.get('update', {})
        raw = update.get('rawInput', {})
        cmd = raw.get('command', '')
        if cmd:
            if isinstance(cmd, list):
                cmd_str = cmd[2] if len(cmd) > 2 else str(cmd)
            else:
                cmd_str = str(cmd)
            if 'kspec' in cmd_str.lower() and 'task' in cmd_str.lower():
                print(json.dumps({
                    'seq': ev.get('seq'),
                    'su': update.get('sessionUpdate'),
                    'cmd': cmd_str[:100],
                    'type': type(cmd).__name__,
                }))
    except:
        pass
EOF

