    // updated by command 1 via the buffer, not from disk.
    const result = kspecJson<BatchExecResult>(
      `batch --commands '[{"command":"inbox add","args":{"text":"first buf item"}},{"command":"inbox add","args":{"text":"second buf item"}}]'`,
