          {
            _ulid: "01NOTE3",
            created_at: "2024-01-03T00:00:00Z",
            author: "@test",
            content: "Trying again",
          },
          {
            _ulid: "01NOTE4",
            created_at: "2024-01-04T00:00:00Z",
            author: "@test",
            content: "[LOOP-FAIL:2] Second failure",
          },
        ],
      };

      expect(getTaskFailureCount(task)).toBe(2);

