/**
 * Ralph command - automated task loop via ACP.
 *
 * Runs an ACP-compliant agent in a loop to process tasks autonomously.
 * Uses session event storage for full audit trail and streaming output.
 */

import { spawn, spawnSync } from "node:child_process";
import { createWriteStream, type WriteStream } from "node:fs";
import * as fs from "node:fs/promises";
import { createRequire } from "node:module";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import chalk from "chalk";
import type { Command } from "commander";
import { ulid } from "ulid";

// Read version from package.json for ACP client info
const require = createRequire(import.meta.url);
const { version: packageVersion } = require("../../../package.json");
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DEFAULT_KSPEC_CLI_PATH = path.resolve(__dirname, "..", "index.js");

import type { ACPClient } from "../../acp/client.js";
import type {
  ReadTextFileRequest,
  RequestPermissionRequest,
  SessionUpdate,
  WriteTextFileRequest,
} from "../../acp/index.js";
import {
  type AgentAdapter,
  registerAdapter,
  resolveAdapter,
} from "../../agents/index.js";
import { type SpawnedAgent, spawnAndInitialize } from "../../agents/spawner.js";
import {
  initContext,
  type KspecContext,
  loadAllItems,
  loadMetaContext,
  type LoadedSkill,
  loadAllTasks,
  type LoadedTask,
  ReferenceIndex,
} from "../../parser/index.js";
import { resolveSkillReferenceTokensForPlatform } from "../../parser/skill-render.js";
import {
  buildWrapUpContext,
  createCliRenderer,
  createTranslator,
  DEFAULT_SUBAGENT_PREFIX,
  DEFAULT_WRAPUP_TIMEOUT,
  type ExitReason,
  formatJsonSection,
  type PromptSection,
  RALPH_PROMPT_TIMEOUT,
  runSubagent,
  runWrapUpAgent,
  type SubagentContext,
  truncatePromptIfNeeded,
  WORKER_PROMPT_MAX_BYTES,
  WRAPUP_AGENT_PREFIX,
} from "../../ralph/index.js";
import {
  appendEvent,
  closeSession,
  createSessionWithBudget,
  getSessionBudgetPath,
  getSessionDir,
  injectEnvForAdapter,
  isEndLoopRequested,
  removeEnvForAdapter,
  requestEndLoop,
  resetBudget,
  saveSessionContext,
} from "../../sessions/index.js";
import { errors } from "../../strings/index.js";
import { getCurrentBranch } from "../../utils/git.js";

