        tools: ["kspec", "git", "npm"],
        dispatch: [
          { on: "task.ready", filter: { automation: "eligible" } },
          { on: "task.needs_work", filter: { automation: "eligible" } },
        ],
        skills: ["task-work"],
        concurrency: { max_concurrent: 1 },
        auto_approve: true,
      },
      {
        id: "pr-reviewer",
