   319→  function spawnRalphUntil(
   320→    args: string[],
   321→    marker: string,
   322→    env: Record<string, string> = {},
   323→  ): Promise<{ output: string }> {
   324→    return new Promise((resolve, reject) => {
   325→      const child = nodeSpawn("node", [CLI_PATH, "ralph", ...args], {
   326→        cwd: tempDir,
   327→        env: {
   328→          ...process.env,
   329→          KSPEC_AUTHOR: "@test",
   330→          ...env,
   331→        },
   332→        stdio: ["pipe", "pipe", "pipe"],
   333→      });
   334→
   335→      let output = "";
   336→      let resolved = false;
   337→
   338→      const onData = (d: Buffer) => {
   339→        output += d.toString();
   340→        // Once we see the marker, cleanup is done — give a small grace period then kill
   341→        if (!resolved && output.includes(marker)) {
   342→          resolved = true;
   343→          setTimeout(() => {
   344→            child.kill("SIGKILL");
   345→            resolve({ output });
   346→          }, 500);
   347→        }
   348→      };
   349→      child.stdout!.on("data", onData);
   350→      child.stderr!.on("data", onData);
   351→
   352→      child.on("close", () => {
   353→        if (!resolved) {
   354→          resolved = true;
   355→          resolve({ output });
   356→        }
   357→      });
   358→
   359→      // Safety timeout
   360→      setTimeout(() => {
   361→        if (!resolved) {
   362→          resolved = true;
   363→          child.kill("SIGKILL");
   364→          reject(new Error(`Timed out waiting for marker "${marker}"\noutput: ${output}`));
