  it("should allow task start when KSPEC_SESSION_ID is set and budget available", async () => {
    const sessionId = testUlid("RENV", 2);
    await createSessionWithBudget(tempDir, {
      id: sessionId,
      agent_type: "claude-code",
      budget: 5,
