describe("ac-env-inject: spawnAgent passes KSPEC_SESSION_ID to child process", () => {
  let tempDir: string;
  let envFile: string;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "kspec-ralph-spawn-"));
